import math
def normalize_fraction(numerator, denominator):
    if type(numerator) is not int or type(denominator) is not int or denominator==0:
        raise ValueError('invalid fraction')
    factor=math.gcd(numerator,denominator)
    n,d=numerator//factor,denominator//factor
    return (-n,-d) if d<0 else (n,d)

def integer_power(base, exponent):
    if type(base) is not int or type(exponent) is not int or exponent<0:
        raise ValueError('invalid exponentiation')
    return pow(base,exponent)

def reverse_low_bits(value, width):
    if type(value) is not int or type(width) is not int or width<0 or value<0 or value>=2**width:
        raise ValueError('invalid bit range')
    result=0
    for _ in range(width):
        result=(result<<1)|(value&1)
        value>>=1
    return result

def unescape_controls(text):
    result=[]
    i=0
    mapping={'n':'\n','t':'\t','\\':'\\'}
    while i<len(text):
        if text[i]=='\\':
            i+=1
            if i==len(text) or text[i] not in mapping:
                raise ValueError('invalid escape')
            result.append(mapping[text[i]])
        else:
            result.append(text[i])
        i+=1
    return ''.join(result)

import re
def title_ascii_words(text):
