class Door:
    def __init__(self):
        self.state='locked'
    def apply(self, action):
        changes={('locked','unlock'):'closed',('closed','open'):'open',('open','close'):'closed',('closed','lock'):'locked'}
        if not isinstance(action,str) or (self.state,action) not in changes:
            raise ValueError('invalid transition')
        self.state=changes[self.state,action]
        return self.state

